function validate([width, height, sideLength, maxOnes]) {
  if (!Number.isInteger(width) || width < 1 || width > 100) return 'width is between 1 and 100.';
  if (!Number.isInteger(height) || height < 1 || height > 100) return 'height is between 1 and 100.';
  if (!Number.isInteger(sideLength) || sideLength < 1 || sideLength > Math.min(width, height)) return 'sideLength is between 1 and the smaller of width and height.';
  if (!Number.isInteger(maxOnes) || maxOnes < 0 || maxOnes > sideLength * sideLength) return 'maxOnes is between 0 and sideLength squared.';
  return null;
}

