function maximumNumberOfOnes(width, height, sideLength, maxOnes) {
  const counts = [];

  for (let row = 0; row < sideLength; row++) {
    for (let col = 0; col < sideLength; col++) {
      const rowCopies = Math.floor((height - row - 1) / sideLength) + 1;
      const colCopies = Math.floor((width - col - 1) / sideLength) + 1;
      counts.push(rowCopies * colCopies);
    }
  }

  counts.sort((a, b) => b - a);
  let ones = 0;
  for (let i = 0; i < maxOnes; i++) {
    ones += counts[i];
  }
  return ones;
}

