function maximumNumberOfOnes(width, height, sideLength, maxOnes) {
  // Try every 0/1 grid as a bit mask (bit r * width + c is cell (r, c)) and keep the best allowed one.
  const cells = width * height;
  let best = 0;
  let mask = 0;
  const cell = (r, c) => (mask >> (r * width + c)) & 1;
  for (mask = 0; mask < 2 ** cells; mask++) {
    let total = 0;
    for (let r = 0; r < height; r++) for (let c = 0; c < width; c++) total += cell(r, c);
    if (total <= best) continue;
    let allowed = true;
    for (let top = 0; top + sideLength <= height && allowed; top++)
      for (let left = 0; left + sideLength <= width && allowed; left++) {
        let count = 0;
        for (let r = top; r < top + sideLength; r++) for (let c = left; c < left + sideLength; c++) count += cell(r, c);
        if (count > maxOnes) allowed = false;
      }
    if (allowed) best = total;
  }
  return best;
}

