function generate(rand, size) {
  if (size === 'large') {
    const width = 40 + Math.floor(rand() * 61);
    const height = 40 + Math.floor(rand() * 61);
    const sideLength = 1 + Math.floor(rand() * Math.min(width, height, 30));
    const maxOnes = Math.floor(rand() * (sideLength * sideLength + 1));
    return [width, height, sideLength, maxOnes];
  }
  for (;;) {
    const width = 1 + Math.floor(rand() * 5);
    const height = 1 + Math.floor(rand() * 5);
    if (width * height > 16) continue;
    const sideLength = 1 + Math.floor(rand() * Math.min(width, height));
    const maxOnes = Math.floor(rand() * (sideLength * sideLength + 1));
    return [width, height, sideLength, maxOnes];
  }
}
